css:
:root{--accent:#e2231a}
.card h3,.card p{color:#1a1a1a}
.card .date,.card .cat,.card .tags{color:#8a8a8a}
.card .badge{background:var(--accent);color:#fff;font-size:9px;letter-spacing:.12em;padding:3px 8px;border-radius:0}
/* 文中1点だけ色を置く */
h3 em{font-style:normal;color:#b08d4a}
/* 2案の識別をピル1個に担わせる */
.card{background:#eef1f5;border:0;border-radius:14px}
.badge--a{background:#1eaede;color:#fff;border-radius:999px;padding:5px 14px;font-size:12px}
.badge--b{background:#f4525f}
